syntax:
Return type FunctionName(parameters) { 
  ReturnType object; // local object potentially optimized away
  // ... object construction ...
  return object; 
}

code_example:
#include <iostream>
#include <string>
struct LargeObject {
  std::string data; 
  LargeObject(const std::string& d) : data(d) { std::cout << "LargeObject constructed\n"; }
  LargeObject(const LargeObject& other) : data(other.data) { std::cout << "LargeObject copy-constructed\n"; }
  LargeObject(LargeObject&& other) noexcept : data(std::move(other.data)) { std::cout << "LargeObject move-constructed\n"; }
};
LargeObject createLargeObject() {
  LargeObject obj("This is a large object");
  return obj;
}
int main() {
  auto lo = createLargeObject();
  std::cout << lo.data << "\n";
  return 0;
}
